import React, { HTMLAttributes } from 'react';

import Bike from '@pohodnik/icons/svg/Sports/Bike';
import CrossCountrySkiing from '@pohodnik/icons/svg/Sports/CrossCountrySkiing';
import Hiking from '@pohodnik/icons/svg/Sports/Hiking';
import Homework from '@pohodnik/icons/svg/Sports/Homework';
import Kayaking from '@pohodnik/icons/svg/Sports/Kayaking';
import Run from '@pohodnik/icons/svg/Sports/Run';
import Walk from '@pohodnik/icons/svg/Sports/Walk';

import { IWorkout } from '../@types/workouts.types';

interface IWorkoutTypeIconProps extends HTMLAttributes<SVGElement> {
  type: IWorkout['type'];
}

const WorkoutTypeIcon: React.FC<IWorkoutTypeIconProps> = ({ type, ...rest }) => {
  if (type.id === 1) return <Hiking {...rest} />;
  if (type.id === 2) return <CrossCountrySkiing {...rest} />;
  if (type.id === 3) return <Run {...rest} />;
  if (type.id === 4) return <Bike {...rest} />;
  if (type.id === 5) return <Walk {...rest} />;
  if (type.id === 6) return <Kayaking {...rest} />;

  return <Homework {...rest} />;
};

export default WorkoutTypeIcon;
